"""Writes vars.cpp: the Neon 16x8 Hadamard kernels of several versions of RdCost_neon.cpp, side by side, for timing on
the Arm CI runner. usage: make_vars2.py <output vars.cpp> <RdCost_neon.cpp of V0> [<RdCost_neon.cpp of V1> ...]
V0 is expected to be master (it overflows for 12-bit residuals, so it is a speed reference only).
Each version's helpers (the code between the "#if ENABLE_SIMD_OPT_DIST" line and the first kernel) and its
xCalcHAD16x8_neon are copied, with every function they define renamed to <name>_V<n>.
"""
import re
import sys

out_path = sys.argv[1]
versions = sys.argv[2:]

parts = ['''// Generated by make_vars2.py: xCalcHAD16x8_neon of several versions (see there).
#include <arm_neon.h>
#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <vector>

#include "CommonLib/RdCost.h"
#include "CommonLib/arm/neon/sum_neon.h"
#include "CommonLib/arm/neon/transpose_neon.h"

namespace vvenc
{
''']

for n, path in enumerate(versions):
    src = open(path, encoding="utf-8").read().replace("\r\n", "\n")
    begin = src.index("\n", src.index("#if ENABLE_SIMD_OPT_DIST && defined( TARGET_SIMD_ARM )")) + 1
    helpers = src[begin:src.index("Distortion xCalcHAD16x16_fast_neon(")]
    start = src.index("Distortion xCalcHAD16x8_neon(")
    kernel = src[start:src.index("\n}\n", start) + 3]
    names = re.findall(r"^static inline \w+ (\w+)\(", helpers, re.M) + ["xCalcHAD16x8_neon"]
    code = helpers + kernel
    for name in names:
        code = re.sub(r"\b%s\(" % name, "%s_V%d(" % (name, n), code)
    parts.append("// ---- V%d: %s\n" % (n, path.replace("\\", "/").split("/")[-1]) + code)

kernels = ", ".join("xCalcHAD16x8_neon_V%d" % n for n in range(len(versions)))
parts.append('''
}   // namespace vvenc

using namespace vvenc;
typedef Distortion ( *Kernel )( const Pel*, const Pel*, const ptrdiff_t, const ptrdiff_t );

int main( int argc, char** argv )
{
  const long calls = argc > 1 ? atol( argv[1] ) : 2000000;
  const Kernel kernels[] = { KERNELS };
  const int numKernels = sizeof( kernels ) / sizeof( kernels[0] );

  RdCost scalar;
  scalar.create( /*enableOpt=*/false );

  const int stride = 256 + 64;
  std::vector<Pel> org( stride * 256 ), cur( stride * 256 );

  // exactness against the C code: random 10-bit, and residuals of +-2046 (V0, master, fails those)
  srand( 3 );
  std::vector<int> bad( numKernels, 0 );
  for( int trial = 0; trial < 4000; trial++ )
  {
    const int pattern = trial % 4;   // 0: random 10-bit, 1: +2046, 2: -2046, 3: random signs of 2046
    for( size_t i = 0; i < org.size(); i++ )
    {
      if( pattern == 0 ) { org[i] = Pel( rand() & 1023 ); cur[i] = Pel( rand() & 1023 ); continue; }
      const bool positive = pattern == 1 || ( pattern == 3 && ( rand() & 1 ) );
      org[i] = Pel( positive ? 2046 : -1023 );
      cur[i] = Pel( positive ? 0 : 1023 );
    }
    DistParam dp;
    dp.org.buf = org.data(); dp.org.stride = stride; dp.org.width = 16; dp.org.height = 8;
    dp.cur.buf = cur.data(); dp.cur.stride = stride;
    dp.bitDepth = 10; dp.applyWeight = 0;
    const Distortion ref = scalar.m_afpDistortFunc[0][DF_HAD16]( dp );
    for( int v = 0; v < numKernels; v++ )
    {
      bad[v] += kernels[v]( org.data(), cur.data(), stride, stride ) != ref;
    }
  }
  for( int v = 0; v < numKernels; v++ )
  {
    printf( "V%d mismatches against the C code: %d of 4000\\n", v, bad[v] );
  }

  srand( 1 );
  for( auto& v : org ) v = Pel( rand() & 1023 );
  for( size_t i = 0; i < cur.size(); i++ ) cur[i] = Pel( std::min( 1023, std::max( 0, org[i] + ( rand() % 64 ) - 32 ) ) );

  std::vector<double> best( numKernels, 1e9 );
  for( int round = 0; round < 5; round++ )
  {
    for( int v = 0; v < numKernels; v++ )
    {
      uint64_t checksum = 0;
      const auto start = std::chrono::steady_clock::now();
      for( long i = 0; i < calls; i++ )
      {
        const int x = ( i * 37 ) % ( 256 - 16 ), y = ( i * 11 ) % ( 256 - 8 );
        checksum += kernels[v]( &org[y * stride + x], &cur[( ( y + 3 ) % ( 256 - 8 ) ) * stride + x], stride, stride );
      }
      const double ns = std::chrono::duration<double, std::nano>( std::chrono::steady_clock::now() - start ).count() / calls;
      best[v] = std::min( best[v], ns );
      printf( "round %d V%d %7.2f ns/call checksum %llu\\n", round, v, ns, (unsigned long long) checksum );
    }
  }
  for( int v = 0; v < numKernels; v++ )
  {
    printf( "V%d best %7.2f ns/call (%+.1f %% against V0)\\n", v, best[v], ( best[v] / best[0] - 1 ) * 100 );
  }
  return 0;
}
'''.replace("KERNELS", kernels))
open(out_path, "w", encoding="utf-8").write("\n".join(parts))
print("ok:", len(versions), "versions")
